function addMany(list){list.forEach(add)}
function esc(s){return String(s??'').replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]))}
function fmt(n){if(n===undefined||n===null||Number.isNaN(Number(n)))return '–';let v=Math.round(Number(n)*100)/100;return String(v).replace('.',',')}
