function initFloatingTools(){
 injectToolStyles();
 if(document.getElementById('notesFloatBtn'))return;
 const noteBtn=document.createElement('button');noteBtn.id='notesFloatBtn';noteBtn.className='floatToolBtn noPrint';noteBtn.title='Notizen öffnen';noteBtn.textContent='📝';noteBtn.onclick=()=>toggleNotes();
 const calcBtn=document.createElement('button');calcBtn.id='calcFloatBtn';calcBtn.className='floatToolBtn noPrint';calcBtn.title='Taschenrechner öffnen';calcBtn.textContent='🧮';calcBtn.onclick=()=>toggleCalculator();
 const notes=document.createElement('section');notes.id='notesPanel';notes.className='toolPanel notesPanel noPrint';notes.innerHTML=`<div class="toolHead"><h3>📝 Notizen</h3><button class="miniX" onclick="toggleNotes(false)">×</button></div><textarea id="globalNotes" class="notesText" placeholder="Hier kannst du dir Rechenwege, Formeln oder Fragen merken … wird automatisch gespeichert."></textarea><p class="calcMsg">Speichert automatisch in diesem Browser.</p>`;
 const calc=document.createElement('section');calc.id='calcPanel';calc.className='toolPanel calcPanel noPrint';calc.innerHTML=`<div class="toolHead"><h3>🧮 Taschenrechner</h3><button class="miniX" onclick="toggleCalculator(false)">×</button></div><div id="calcBlockMsg"></div><div id="calcDisplay" class="calcDisplay">0</div><div class="calcGrid">${['C','⌫','(',')','7','8','9','÷','4','5','6','×','1','2','3','−','0',',','π','+','√','x²','^','='].map(k=>`<button class="calcKey ${['÷','×','−','+','√','x²','^','='].includes(k)?'op':''} ${k==='='?'eq':''}" onclick="calcPress('${k}')">${k}</button>`).join('')}</div><p class="calcMsg">Tipp: Für Prüfungsmodus Teil 1 und einfache Kopfrechenaufgaben wird der Rechner gesperrt.</p>`;
 document.body.append(noteBtn,calcBtn,notes,calc);
 const ta=document.getElementById('globalNotes');ta.value=localStorage.getItem(NOTES_KEY)||'';ta.addEventListener('input',()=>localStorage.setItem(NOTES_KEY,ta.value));
 updateCalcDisplay();updateToolAvailability();setInterval(updateToolAvailability,750);
}
function toggleNotes(force){const p=document.getElementById('notesPanel');if(!p)return;const open=typeof force==='boolean'?force:!p.classList.contains('open');p.classList.toggle('open',open);if(open)setTimeout(()=>document.getElementById('globalNotes')?.focus(),50)}
function needsHeadCalculatorBlock(q){
 if(!q)return false;
 if(q.noCalculator || q.examPart==='teil1')return true;
 const p=String(q.prompt||'').toLowerCase();
 const simple=/berechne:\s*[-0-9]|ergänze|lücke|term|gleichung|kopfrechnen|ohne hilfsmittel/.test(p);
 return Boolean(activeQuiz && activeQuiz.mode==='exam' && q.diff==='hard' && q.headCalc && simple);
}
function calcAllowedInfo(){const q=currentQ&&currentQ();if(needsHeadCalculatorBlock(q)){return {allowed:false,reason:q?.examPart==='teil1'?'Teil 1 ist wie in der echten Abschlussarbeit ohne Taschenrechner.':'Diese Aufgabe ist als Kopfrechen-/Rechenweg-Aufgabe markiert. Übe sie ohne Taschenrechner, damit du es in der Arbeit sicher kannst.'}}return {allowed:true,reason:'Taschenrechner erlaubt.'}}
function updateToolAvailability(){const btn=document.getElementById('calcFloatBtn');const msg=document.getElementById('calcBlockMsg');const inline=document.getElementById('calcStatusInline');if(!btn)return;const info=calcAllowedInfo();btn.classList.toggle('blocked',!info.allowed);btn.title=info.allowed?'Taschenrechner öffnen':'Taschenrechner gesperrt: '+info.reason;if(msg)msg.innerHTML=info.allowed?'':`<div class="blockedMsg"><strong>Gesperrt:</strong> ${esc(info.reason)}</div>`;if(inline)inline.textContent=info.allowed?'🧮 Taschenrechner: erlaubt':'🧮 Taschenrechner: gesperrt – '+info.reason;}
function toggleCalculator(force){const p=document.getElementById('calcPanel');if(!p)return;updateToolAvailability();const open=typeof force==='boolean'?force:!p.classList.contains('open');p.classList.toggle('open',open)}
function calcPress(k){const info=calcAllowedInfo();if(!info.allowed){updateToolAvailability();toggleCalculator(true);return}if(k==='C'){calcExpression='';return updateCalcDisplay()}if(k==='⌫'){calcExpression=calcExpression.slice(0,-1);return updateCalcDisplay()}if(k==='=')return calcEvaluate();if(k==='÷')calcExpression+='/';else if(k==='×')calcExpression+='*';else if(k==='−')calcExpression+='-';else if(k===',')calcExpression+='.';else if(k==='π')calcExpression+='π';else if(k==='√')calcExpression+='√(';else if(k==='x²')calcExpression+='^2';else calcExpression+=k;updateCalcDisplay()}
function updateCalcDisplay(value){const d=document.getElementById('calcDisplay');if(!d)return;d.textContent=value??(calcExpression||'0')}
function calcEvaluate(){try{const result=safeCalc(calcExpression);calcExpression=String(Math.round(result*100000000)/100000000).replace('.',',');updateCalcDisplay(calcExpression)}catch(e){updateCalcDisplay('Fehler')}}
function safeCalc(expr){let e=String(expr).replace(/,/g,'.').replace(/π|pi/gi,'(Math.PI)').replace(/√\s*\(/g,'Math.sqrt(').replace(/:/g,'/').replace(/[×·]/g,'*').replace(/−/g,'-').replace(/\^/g,'**');if(!/^[0-9+\-*/().\sMathPIsqrt]+$/.test(e))throw new Error('bad');const val=Function('Math',`"use strict";return (${e})`)(Math);if(!Number.isFinite(val))throw new Error('bad');return val}
document.getElementById('brandBtn').addEventListener('click',renderHome);document.querySelectorAll('[data-screen]').forEach(btn=>btn.addEventListener('click',()=>{const s=btn.dataset.screen;if(s==='home')renderHome();if(s==='learn')renderLearn();if(s==='setup')renderSetup();if(s==='progress')renderProgress();if(s==='videos')renderVideos();if(s==='exam')renderExamMode()}));document.getElementById('themeBtn').addEventListener('click',()=>setTheme(document.body.classList.contains('dark')?'light':'dark'));document.getElementById('formulaToggle').addEventListener('click',()=>toggleFormula());document.getElementById('formulaClose').addEventListener('click',()=>toggleFormula(false));document.getElementById('formulaBackdrop').addEventListener('click',()=>toggleFormula(false));renderFormulaPanel();setTheme(localStorage.getItem(THEME_KEY)||'light');renderHome();initFloatingTools();
